18	/// Parses a CSS query feature used by `@media` and `@container`.
19	#[inline]
20	pub fn parse_any_query_feature(p: &mut CssParser) -> ParsedSyntax {
21	    if is_at_scss_interpolation(p) {
22	        parse_interpolated_query_feature(p)
23	    } else if is_at_query_feature_name(p) {
24	        parse_named_query_feature(p)
25	    } else if is_at_value_prefixed_query_feature(p) {
26	        parse_value_prefixed_query_feature(p)
27	    } else {
28	        Absent
29	    }
30	}
